import json,pathlib,html
p=pathlib.Path(__file__).parent
f=p/'references.json';d=json.loads(f.read_text());refs=d['references']; byid={r['id']:r for r in refs}
def mid(s):
 matches=[r['id'] for r in refs if r['id'].split(':',1)[1].startswith(s)]
 assert len(matches)==1,(s,matches)
 return matches[0]
def cite(s):
 i=mid(s);return f'{byid[i]["app"]} [{i}]'
def link(s):
 i=mid(s);r=byid[i];return '<a href="#ref-'+__import__('urllib.parse',fromlist=['quote']).quote(i,safe='')+'" title="'+html.escape(i)+'">'+html.escape(r['app']+' · '+i.split(':')[0]+':'+i.split(':')[1][:8]+'…')+'</a>'
def sentence(text,*ids):return text+' '+ '; '.join(link(s) for s in ids)+'.'
answers=[
'Publication is layered in these captures. '+cite('9ef7d498')+' shows lesson Publish controls and a Drip panel based on days after enrolment. '+cite('9aa981d2')+' shows Draft, Publish, Drip and Lock in a module menu, followed by a Published state. '+cite('94f6be70')+' separates Published, Open and Visible and shows a delayed module. '+cite('ec16c800')+' explains Open, Private and Secret audiences. For Essentials, make course publication, audience scope and item release separately legible. The captures do not establish the consequences of unpublishing an active course.',
'Grant access in the context of the course. '+cite('e801d8ae')+' shows invitations with selected-space access and privileged-role controls. '+cite('b227715d')+' combines email invitations, copy link and visible permissions; '+cite('ffaf7085')+' adds Anyone access, View/Edit and password protection. '+cite('44650693')+' names a Member role in an email invitation. These are access patterns, not a prescribed role model for learners. A password is not evidence of a classroom join-code workflow; enrolled-group inheritance and class codes remain unverified in this set.',
'Preview has different scopes. '+cite('02f1cfb0')+' explicitly labels preview as an enrolled member and retains lesson content and a completion action. '+cite('5c96453b')+' places View as learner beside the course editor. '+cite('e6757446')+' exposes curriculum preview without proving the same role simulation. '+cite('56f720b3')+' previews an AI activity as a student, which is narrower than a whole course portal. For Essentials, label the simulated learner and group; confirm separately whether release dates, prerequisites and progress writes are simulated. Those behaviours are not established by the screenshots.',
'Day one needs a clear next action. '+cite('c04c0023')+' shows Start Lesson, the lesson list and 0% completion. '+cite('18683325')+' prioritises Continue learning, progress, Resume and a weekly goal. '+cite('afde5712')+' provides community context and content entry points. For simulation education, adapt the next-action pattern to the next scheduled session and required preparation; these captures do not establish a session-first portal. Treat announcements as context from module 09 and recordings/reports as a hand-off to 08.',
'Publishing, inviting, joining and learning are different events. '+cite('6462b667')+' shows Customer invited alongside audience rows and progress; this supports an action confirmation and participation context, not email-open telemetry. '+cite('2fe9271e')+' exposes Pending and Accepted tabs plus bounced, resent and revoked invitation states. Pending does not prove delivery. For Essentials, show the recipient, current access and available recovery action, then distinguish invitation status from first course access and learning progress. No retained capture demonstrates a course-open event.',
'Only Coursera has a matched web/iOS course-home pair in this set: '+cite('f31fedca')+' and '+cite('d76cce29')+'. Both expose progress and the next learning action; goals and navigation adapt to the device. The iOS Download button shows an available action, not verified offline behaviour. '+cite('89b6481f')+' is Udemy mobile context without a matched web capture; '+cite('be865fb9')+' is a Teachable learner-facing preview inside an admin shell, not a verified ordinary learner session; no matched mobile capture was retained. Preserve shared learner state and the next action across devices, but validate invitation entry, authentication and session joining separately.'
]
for q,a in zip(d['questions'],answers):q['answer']=a
answers[1] += ' '+cite('157502c1')+' makes a 30-day trial limit explicit before inviting a customer. '+cite('11b3c0a4')+' is a creator-side counter-example: Share and Collaborators navigation do not establish a learner-access workflow.'
answers[4] += ' '+cite('a906866c')+' confirms the course is ready, reports team notification and offers Classwork and Copy link; it does not enumerate learner acceptance.'
for q,a in zip(d['questions'],answers):q['answer']=a
# Counter-examples are scoped contrasts, not claims that products lack unseen features.
for r in refs:
 r['counter_example']=r['id'] in [mid('56f720b3'),mid('e6757446'),mid('11b3c0a4')]
 r['selected']=False
 if r['id']==mid('56f720b3'):r['take']='Counter-example in scope: “Previewing as a student” and Restart preview are visible for an AI activity; this does not establish whole-course or cohort-access preview.'
 if r['id']==mid('e6757446'):r['take']='Counter-example in scope: Curriculum Preview is visible in the author setup flow; the retained steps do not establish the explicit enrolled-member simulation shown by Circle.'
f.write_text(json.dumps(d,indent=2))
parts=['<section id="synthesis" aria-label="Research synthesis" style="margin:28px 0;padding:24px;border:1px solid var(--border);border-radius:8px;background:var(--surface)">','<h3>Top examples</h3><ol>']
top=[('9ef7d498','Teachable separates lesson publication from enrolment-relative release timing.'),('ec16c800','Circle makes audience visibility choices understandable at publication.'),('94f6be70','Podia names publication, access and discoverability separately.'),('b227715d','Figma combines direct invitations, a share link and visible permissions.'),('02f1cfb0','Circle labels the enrolled-member preview context.'),('c04c0023','Teachable gives a new learner an obvious Start Lesson action.'),('18683325','Coursera foregrounds progress and Resume for a returning learner.'),('2fe9271e','Slack makes failed and pending invitations operationally manageable.')]
for s,t in top:
 r=byid[mid(s)];parts.append('<li>'+html.escape(t)+' '+link(s)+' · '+r['source'].title()+'</li>')
parts+=['</ol><h3>Pattern comparison</h3><p>Coverage of captured evidence, not a product feature score. ✓ = directly observed for the question; partial = adjacent, incomplete or not observed; ✗ would mean an explicitly observed contrary behaviour. No absent feature is inferred from missing captures. Column titles repeat Q1–Q6 below.</p>','<div role="region" aria-label="Product comparison" tabindex="0" style="overflow-x:auto"><table style="border-collapse:collapse;min-width:1150px;width:100%;font-size:13px"><thead><tr><th style="text-align:left;padding:10px">Product</th>']
for q in d['questions']:parts.append('<th scope="col" style="text-align:left;vertical-align:top;padding:10px;min-width:170px">'+html.escape(q['id']+' · '+q['title'])+'</th>')
parts.append('</tr></thead><tbody>')
cells={}
for n in range(1,7):
 for c in json.loads((p/f'notes/Q{n}-cells.json').read_text()):
  valid=[i for i in c['ids'] if i in byid]
